from browser_validation import *
run('set','viewport',1280,800);snap();click('Reset all settings');click('Pause simulation');click('Render','tab');click('Performance');run('uncheck','#adaptive');run('uncheck','#taa');click('Environment','tab');snap()
for key,value in [('spin',-.8),('horizon',1.8),('inner',5),('outer',14),('thickness',.55),('inclination',35),('temperature',11500),('turbulence',0)]:
    a=state();range_to(key,value);b=state();check('rendered parameter '+key,a['p']['hash']!=b['p']['hash'] and a['d']['settings'][key]!=b['d']['settings'][key],{'before':a['d']['settings'][key],'after':b['d']['settings'][key],'hashes':[a['p']['hash'],b['p']['hash']],'glError':b['p']['glError']})
shot('altered-disk-geometry.png');range_to('outer',4);range_to('inner',8);s=state();check('disk radius ordering guard',s['d']['settings']['inner']<s['d']['settings']['outer'],{'inner':s['d']['settings']['inner'],'outer':s['d']['settings']['outer']})
click('Render','tab')
for key,value in [('exposure',.5),('contrast',.8),('bloom',1.4)]:
    a=state();range_to(key,value);b=state();check('image development '+key,a['p']['hash']!=b['p']['hash'],{'before':a['d']['settings'][key],'after':b['d']['settings'][key],'means':[a['p']['mean'],b['p']['mean']]})
range_to('resolution',.65);s=state();check('manual internal resolution',s['d']['internalSize']==[627,407],{'actual':s['d']['internalSize'],'scale':s['d']['settings']['resolution']})
click('Reset all settings');click('Pause simulation');click('Render','tab');click('Performance');run('uncheck','#adaptive');run('uncheck','#taa');click('Environment','tab');range_to('spin',0);run('select','#viewMode','6');state()
comparison=ev('''(()=>{let c=document.getElementById('universe'),g=c.getContext('webgl2'),out=[];for(let [fx,fy] of [[.5,.5],[.1,.9],[.85,.8],[.2,.47],[.75,.49],[.35,.57],[.7,.63]]){let x=Math.floor(fx*c.width),y=Math.floor(fy*c.height),a=new Uint8Array(4);g.readPixels(x,y,1,1,g.RGBA,g.UNSIGNED_BYTE,a);let r=Horizon.traceRay((x+.5)/c.width*2-1,(y+.5)/c.height*2-1);out.push({pixel:[x,y],rgb:[...a].slice(0,3),cpu:r.state,disk:!!r.hit,steps:r.steps,bend:r.bend});}return out})()''')
def expected(r):
    return [26,31,43] if r['cpu']=='Captured' else ([66,179,158] if r['disk'] else [56,112,186]) if r['cpu']=='Escaped' else [247,153,48] if r['cpu']=='Step limit' else [255,0,166]
check('GPU classification agrees with CPU reference',all(max(abs(x-y) for x,y in zip(r['rgb'],expected(r)))<=2 for r in comparison),comparison)
click('Render','tab');range_to('maxSteps',512);range_to('step',.6);a=ev('(()=>{let r=Horizon.traceRay(.42,.15);return {bend:r.bend,steps:r.steps,nearest:r.nearest,state:r.state,energy:r.energyDrift}})()');range_to('step',.3);b=ev('(()=>{let r=Horizon.traceRay(.42,.15);return {bend:r.bend,steps:r.steps,nearest:r.nearest,state:r.state,energy:r.energyDrift}})()');check('integration converges as step is refined',a['state']==b['state']=='Escaped' and abs(a['bend']-b['bend'])<1 and b['energy']<a['energy'],{'coarse':a,'fine':b})
run('select','#viewMode','0');a=state();range_to('simTime',120);b=state();check('simulation time changes disk turbulence image',a['d']['time']!=b['d']['time'] and a['p']['hash']!=b['p']['hash'] and b['d']['paused'],{'times':[a['d']['time'],b['d']['time']],'hashes':[a['p']['hash'],b['p']['hash']]})
click('Balanced');run('check','#adaptive');click('Resume simulation');run('wait','--fn','Horizon.diagnostics.adaptiveScale<1');s=state();check('adaptive resolution responds to measured frame rate',s['d']['adaptiveScale']<1,{'scale':s['d']['adaptiveScale'],'fps':s['d']['fps'],'dimensions':s['d']['internalSize'],'quality':s['d']['settings']['quality']});click('Pause simulation')
